 "content": "def transform(grid):
    # Compare the two repeated patterned bands: mark in the first band
    # (with color 1) cells present in the second band but absent in the first.
    h, w = len(grid), len(grid[0])
    active = [r for r, row in enumerate(grid) if any(v != 9 for v in row)]
    if not active:
        return [row[:] for row in grid]
    # Split at blank rows into two nonblank bands.
    bands = []
    for r in active:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    out = [row[:] for row in grid]
    if len(bands) >= 2:
        a, b = bands[0], bands[-1]
        for i, r in enumerate(a):
            if i < len(b):
                for c in range(w):
                    if grid[r][c] == 9 and grid[b[i]][c] != 9:
                        out[r][c] = 1
    return out
