        p=best
        # Detect a run of background at the end after a repeated non-bg cycle.
        # Look for the longest periodic prefix and mark positions where that
        # pattern predicts non-bg but the observed value is bg.
        for start in range(0,n-2*p+1):
            if all(row[i]==row[i%p] for i in range(start,n) if i%p < p):
