        # Extrapolate only over the trailing segment that departs from pattern.
        for c in range(n-1,-1,-1):
            if row[c]!=row[c-p] if c>=p else True:
                break
        # Consider pattern anchored by the first p cells; mark trailing misses.
        for c in range(p,n):
            pred=row[c-p]
            if row[c]!=pred and row[c]==max(set(row),key=row.count) and pred!=row[c]:
                out[r][c]=1
    return out
